from itertools import permutations

def solve_puzzle():
    people = ['Blake', 'Casey', 'Harper', 'Morgan', 'Sawyer']
    colors = ['blue', 'green', 'orange', 'red', 'yellow']
    pets = ['bird', 'dog', 'fish', 'horse', 'rabbit']
    drinks = ['cocoa', 'coffee', 'juice', 'milk', 'tea']
    hobbies = ['baking', 'fencing', 'hiking', 'painting', 'rowing']

    # Try all possible permutations
    for perm_people in permutations(people):
        for perm_colors in permutations(colors):
            for perm_pets in permutations(pets):
                for perm_drinks in permutations(drinks):
                    for perm_hobbies in permutations(hobbies):
                        # Build assignment for houses 0-4
                        houses = {}
                        for i in range(5):
                            houses[i] = {
                                'person': perm_people[i],
                                'color': perm_colors[i],
                                'pet': perm_pets[i],
                                'drink': perm_drinks[i],
                                'hobby': perm_hobbies[i]
                            }

                        # Check all constraints
                        if check_constraints(houses):
                            return houses

    return None

def check_constraints(h):
    def get_pos(attr, val):
        for i in range(5):
            if h[i][attr] == val:
                return i
        return -1

    def adj(p1, p2):
        return abs(p1 - p2) == 1

    def imm_l(p1, p2):
        return p2 - p1 == 1

    try:
        # All 16 constraints
        if not (get_pos('color', 'orange') != get_pos('hobby', 'painting')): return False  # 1
        if not (get_pos('pet', 'horse') != get_pos('person', 'Blake')): return False  # 2
        if not imm_l(get_pos('color', 'blue'), get_pos('person', 'Sawyer')): return False  # 3
        if not adj(get_pos('person', 'Casey'), get_pos('hobby', 'hiking')): return False  # 4
        if not imm_l(get_pos('hobby', 'baking'), get_pos('drink', 'tea')): return False  # 5
        if not imm_l(get_pos('hobby', 'baking'), get_pos('pet', 'dog')): return False  # 6
        if not adj(get_pos('pet', 'rabbit'), get_pos('hobby', 'fencing')): return False  # 7
        if not adj(get_pos('drink', 'tea'), get_pos('pet', 'horse')): return False  # 8
        if not adj(get_pos('person', 'Casey'), get_pos('pet', 'bird')): return False  # 9
        if not adj(get_pos('color', 'red'), get_pos('pet', 'rabbit')): return False  # 10
        if not adj(get_pos('drink', 'cocoa'), get_pos('color', 'orange')): return False  # 11
        if not (get_pos('color', 'yellow') == get_pos('hobby', 'rowing')): return False  # 12
        if not (get_pos('pet', 'bird') == get_pos('person', 'Harper')): return False  # 13
        if not (get_pos('person', 'Sawyer') == get_pos('drink', 'juice')): return False  # 14
        if not imm_l(get_pos('color', 'blue'), get_pos('hobby', 'painting')): return False  # 15
        if not (get_pos('pet', 'bird') == get_pos('drink', 'milk')): return False  # 16
        return True
    except:
        return False

# Solve using constraint satisfaction with exhaustive search
solution = solve_puzzle()

if solution:
    # Find who owns the bird
    for i in range(5):
        if solution[i]['pet'] == 'bird':
            print(f"ANSWER: {solution[i]['person']}")
            break
else:
    print("ANSWER: UNKNOWN")
